// Guides are grouped by topic here (test/sidebars.test.mjs checks that every guide in docs/guides is listed once);
// the Reference tree is generated by `npm run apidocs` (.generated/sidebar.json), grouped by namespace and area.
const { existsSync, readFileSync } = require('node:fs');

const reference = existsSync('./.generated/sidebar.json') ? JSON.parse(readFileSync('./.generated/sidebar.json', 'utf8')) : [];

const group = (label, docs, collapsed = true) => ({
  type: 'category',
  label,
  collapsible: true,
  collapsed,
  items: docs.map((doc) => `guides/${doc}`),
});

const guides = [
  'guides/getting-started',
  group('Building an extension', ['project-setup', 'runtime-and-hosting', 'development-loop', 'api-conventions', 'interfaces-at-run-time'], false),
  group('User interface', ['menus', 'messages-panel', 'panels']),
  group('Design data', ['schematic-basics', 'pcb-basics', 'bom', 'design-data-notes']),
  group('Outputs and services', ['outputers', 'altium-365-api']),
  'guides/gotchas',
];

module.exports = {
  docs: [
    'index',
    {
      type: 'category',
      label: 'Guides',
      collapsible: false,
      items: guides,
    },
    {
      type: 'category',
      label: 'Reference',
      collapsible: false,
      link: existsSync('./docs/reference/index.md') ? { type: 'doc', id: 'reference/index' } : undefined,
      items: reference,
    },
  ],
};
